-- steps
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (1, 1, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 90 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 90, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (2, 1, 2, 'core', 'subdivisionCounting', 'How to Count Sixteenth Notes', 'https://www.youtube.com/watch?v=vuk_oC5niP8', 'Count out loud. 8th notes: count "1 and 2 and 3 and 4 and" out loud over a click. Don''t just think it — say it. The coordination between mouth, ears, and hands is the whole point. 5 minutes here saves 50 minutes of confusion later.', 1, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (3, 1, 3, 'apply', NULL, NULL, NULL, 'Drop counted 16th notes over a groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 1.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (4, 2, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Warm up with single strokes at 90 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 90, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (5, 2, 2, 'core', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Single stroke roll at 90 BPM. You''re coming back from a layoff — this should feel familiar fast. Don''t force speed. Push to where it gets sloppy, drop 10 BPM, play clean, push again.', 90, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (6, 2, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 1.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (7, 3, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 90 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 90, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (8, 3, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', 'Single kick placement at 70 BPM. Syncopated pattern — kick on the "e" or "a" of each beat. Start slow. Chunk it: right foot alone, then add hands. Push to where it starts breaking, drop 10 BPM, play clean, then push again.', 70, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (9, 3, 3, 'apply', NULL, NULL, NULL, 'Drop the syncopated kick into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 1.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (10, 4, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Warm up with single strokes at 90 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 90, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (11, 4, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', 'Groove continuously for 2 min. Single kick and hi-hat pattern, whatever feels comfortable. Stop if your forearms cramp — that''s the signal, not failure. Week 1: rebuild the cardio, don''t blow it up.', NULL, 120);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (12, 4, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 1.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (13, 5, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 1.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (14, 6, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Start the session with single strokes at 91 BPM. Week 2 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 91, NULL);
