INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (48, 18, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 4.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (49, 19, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 94 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 94, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (50, 19, 2, 'core', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Single stroke roll at 94 BPM. You''re coming back from a layoff — this should feel familiar fast. Don''t force speed. Push to where it gets sloppy, drop 10 BPM, play clean, push again.', 94, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (51, 19, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 4.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (52, 20, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 4.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (53, 21, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Start the session with single strokes at 95 BPM. Week 5 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 95, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (54, 21, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', 'Single kick placement at 76 BPM. Syncopated pattern — kick on the "e" or "a" of each beat. Start slow. Chunk it: right foot alone, then add hands. Push to where it starts breaking, drop 10 BPM, play clean, then push again.', 76, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (55, 21, 3, 'apply', NULL, NULL, NULL, 'Drop the syncopated kick into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 5.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (56, 22, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Start the session with single strokes at 95 BPM. Week 5 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 95, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (57, 22, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', 'Continuous groove for 6 min 45 sec. You''re 4 weeks into stamina conditioning. The punk muscle memory is coming back — trust it. Don''t stop unless you have to.', NULL, 345);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (58, 22, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 5.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (59, 23, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Start the session with single strokes at 95 BPM. Week 5 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 95, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (60, 23, 2, 'core', 'polyrhythmVsPolymeter', 'How To Easily Explain Polyrhythm vs Polymeter', 'https://www.youtube.com/watch?v=08hmJd1BVKk', '4/16 kick grouping against a steady 4/4 on the hands. Start slow. Chunk it: kick alone first, then hands alone, then combine at 73 BPM. Push to where it starts breaking, drop 10 BPM, play clean, then push again. This is genuinely new territory — treat it like a beginner would.', 73, NULL);
