INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (104, 40, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 8.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (105, 41, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Foundation check. Single strokes at 99 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 99, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (106, 41, 2, 'core', 'jayPostonesOddTime', 'ODD TIMED DRUMMING — Drum Lesson', 'https://www.youtube.com/watch?v=w83rbm4JBo0', '5/16 kick grouping against a steady 4/4 on the hands. Start slow. Chunk it: kick alone first, then hands alone, then combine at 79 BPM. Push to where it starts breaking, drop 10 BPM, play clean, then push again. This is genuinely new territory — treat it like a beginner would.', 79, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (107, 41, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 9.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (108, 42, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Foundation check. Single strokes at 99 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 99, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (109, 42, 2, 'core', 'heelToe', 'Heel-Toe Bass Drum Technique', 'https://www.youtube.com/watch?v=xHqkxHaQ-bI', 'Single kick placement at 83 BPM. Syncopated pattern — kick on the "e" or "a" of each beat. Start slow. Chunk it: right foot alone, then add hands. Push to where it starts breaking, drop 10 BPM, play clean, then push again.', 83, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (110, 42, 3, 'apply', NULL, NULL, NULL, 'Drop the syncopated kick into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 9.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (111, 43, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Foundation check. Single strokes at 99 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 99, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (112, 43, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', '8-minute groove hold. You should own this by now. If it still feels hard, note that — it''s diagnostic. The goal is effortless, not gritted teeth.', NULL, 480);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (113, 43, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 9.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (114, 44, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Foundation check. Single strokes at 99 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 99, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (115, 44, 2, 'core', 'jayPostonesOddTime', 'ODD TIMED DRUMMING — Drum Lesson', 'https://www.youtube.com/watch?v=w83rbm4JBo0', '5/16 kick grouping against a steady 4/4 on the hands. Start slow. Chunk it: kick alone first, then hands alone, then combine at 79 BPM. Push to where it starts breaking, drop 10 BPM, play clean, then push again. This is genuinely new territory — treat it like a beginner would.', 79, NULL);
