INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (117, 45, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 9.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (118, 46, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Warm up with single strokes at 101 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 101, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (119, 46, 2, 'core', 'oddTimeGrooves', 'Go-To Odd Time Grooves', 'https://www.youtube.com/watch?v=mvHa9mokz_I', 'First odd time groove. Start with 5/4: count "1 2 3 4 5" and feel where the downbeat lands each bar. It will feel wrong for a while. That''s normal — you''re retraining where "1" is. Slow click, count out loud.', 1, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (120, 46, 3, 'apply', NULL, NULL, NULL, 'Drop the odd time groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 10.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (121, 47, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 101 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 101, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (122, 47, 2, 'core', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Single stroke roll at 101 BPM. You''re coming back from a layoff — this should feel familiar fast. Don''t force speed. Push to where it gets sloppy, drop 10 BPM, play clean, push again.', 101, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (123, 47, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 10.', NULL, NULL);
