INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (125, 48, 2, 'core', 'jayPostonesOddTime', 'ODD TIMED DRUMMING — Drum Lesson', 'https://www.youtube.com/watch?v=w83rbm4JBo0', '5/16 kick grouping against a steady 4/4 on the hands. Start slow. Chunk it: kick alone first, then hands alone, then combine at 80 BPM. Push to where it starts breaking, drop 10 BPM, play clean, then push again. This is genuinely new territory — treat it like a beginner would.', 80, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (126, 48, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 10.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (127, 49, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 101 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 101, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (128, 49, 2, 'core', 'oddTimeGrooves', 'Go-To Odd Time Grooves', 'https://www.youtube.com/watch?v=mvHa9mokz_I', 'First odd time groove. Start with 5/4: count "1 2 3 4 5" and feel where the downbeat lands each bar. It will feel wrong for a while. That''s normal — you''re retraining where "1" is. Slow click, count out loud.', 1, NULL);
