INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (130, 50, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 10.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (131, 51, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Start the session with single strokes at 102 BPM. Week 11 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 102, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (132, 51, 2, 'core', 'jayPostonesOddTime', 'ODD TIMED DRUMMING — Drum Lesson', 'https://www.youtube.com/watch?v=w83rbm4JBo0', '5/16 polymeter. You''ve had this concept for 8 weeks. Target: 81 BPM. The goal is consistency, not just hitting the number once. 3 clean passes before moving up. Notice which beat of the hand cycle the kick lands on — that drift is the whole point.', 81, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (133, 51, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 11.', NULL, NULL);
