INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (135, 52, 2, 'core', 'oddTimeGrooves', 'Go-To Odd Time Grooves', 'https://www.youtube.com/watch?v=mvHa9mokz_I', 'Odd time groove #1. You''ve been here 1 weeks. Today''s meter: 5/4. Same approach — count out loud first, feel the bar shape before you add dynamics.', 1, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (136, 52, 3, 'apply', NULL, NULL, NULL, 'Drop the odd time groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 11.', NULL, NULL);
