INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (161, 62, 2, 'core', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Single strokes at 104 BPM. Week 13. 12 weeks of consistent work. Check: are you using your wrists or arms? At this tempo it should be wrists. Relax the grip.', 104, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (162, 62, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 13.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (163, 63, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 104 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 104, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (164, 63, 2, 'core', 'jayPostonesOddTime', 'ODD TIMED DRUMMING — Drum Lesson', 'https://www.youtube.com/watch?v=w83rbm4JBo0', '5/16 polymeter. You''ve had this concept for 10 weeks. Target: 84 BPM. The goal is consistency, not just hitting the number once. 3 clean passes before moving up. Notice which beat of the hand cycle the kick lands on — that drift is the whole point.', 84, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (165, 63, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 13.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (166, 64, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Warm up with single strokes at 104 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 104, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (167, 64, 2, 'core', 'oddTimeGrooves', 'Go-To Odd Time Grooves', 'https://www.youtube.com/watch?v=mvHa9mokz_I', 'Odd time groove #2. You''ve been here 3 weeks. Today''s meter: 7/8. Same approach — count out loud first, feel the bar shape before you add dynamics.', 2, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (168, 64, 3, 'apply', NULL, NULL, NULL, 'Drop the odd time groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 13.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (169, 65, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 13.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (170, 66, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Start the session with single strokes at 105 BPM. Week 14 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 105, NULL);
