INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (392, 151, 2, 'core', 'bleedMeshuggah', 'Bleed by Meshuggah — Drum Lesson Breakdown', 'https://www.youtube.com/watch?v=QCBr1ws2JYo', 'combined polymeter at 110 BPM. This is near your ceiling. Use the push-breakdown-drop method. If you can''t play it clean 3 times at this tempo, it''s not your tempo yet. Don''t fake it — the groove has to feel mechanical, not effortful.', 110, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (393, 151, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 31.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (394, 152, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Warm up with single strokes at 125 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 125, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (395, 152, 2, 'core', 'linearSingles', 'How To Play Linear Singles', 'https://www.drumeo.com/beat/how-to-play-linear-singles/', 'Linear fills — variation 4. You''ve had this 11 weeks. Add the new variation today, then play all previous variations back-to-back. Muscle memory builds from repetition, not from learning new things and forgetting old ones.', 4, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (396, 152, 3, 'apply', NULL, NULL, NULL, 'Drop a linear fill into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 31.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (397, 153, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 125 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 125, NULL);
