INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (449, 173, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Start the session with single strokes at 130 BPM. Week 35 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 130, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (450, 173, 2, 'core', 'dannyCarey', 'Danny Carey''s Tools Of The Trade', 'https://www.youtube.com/watch?v=-Emut0-LYJE', 'Odd time at week 35. 13 grooves in your toolkit. Today''s focus: make it feel like 4/4, not like counting. The groove has to become natural, not calculated.', 13, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (451, 173, 3, 'apply', NULL, NULL, NULL, 'Drop the odd time groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 35.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (452, 174, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Start the session with single strokes at 130 BPM. Week 35 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 130, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (453, 174, 2, 'core', 'heelToe', 'Heel-Toe Bass Drum Technique', 'https://www.youtube.com/watch?v=xHqkxHaQ-bI', 'Kick placement at 123 BPM — near ceiling. At this tempo, every mis-hit is audible. Precision over speed: if you can''t land it cleanly, slow down 5 BPM.', 123, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (454, 174, 3, 'apply', NULL, NULL, NULL, 'Drop the syncopated kick into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 35.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (455, 175, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 35.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (456, 176, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Foundation check. Single strokes at 131 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 131, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (457, 176, 2, 'core', 'linearSingles', 'How To Play Linear Singles', 'https://www.drumeo.com/beat/how-to-play-linear-singles/', 'Linear fills at week 36. 6 variations in the toolkit. Today''s goal: chain 3 different variations without stopping. That''s performance-ready linear playing.', 6, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (458, 176, 3, 'apply', NULL, NULL, NULL, 'Drop a linear fill into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 36.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (459, 177, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Foundation check. Single strokes at 131 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 131, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (460, 177, 2, 'core', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Single strokes at 131 BPM. Near the top of the ramp. Play in front of a mirror or camera — at high tempos, technique breaks down invisibly. Watch for grip drift.', 131, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (461, 177, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 36.', NULL, NULL);
