INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (466, 179, 2, 'core', 'bleedMeshuggah', 'Bleed by Meshuggah — Drum Lesson Breakdown', 'https://www.youtube.com/watch?v=QCBr1ws2JYo', 'combined polymeter at 117 BPM. This is near your ceiling. Use the push-breakdown-drop method. If you can''t play it clean 3 times at this tempo, it''s not your tempo yet. Don''t fake it — the groove has to feel mechanical, not effortful.', 117, NULL);
