INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (565, 217, 3, 'apply', NULL, NULL, NULL, 'Drop the single stroke roll into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 44.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (566, 218, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Start the session with single strokes at 141 BPM. Week 44 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 141, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (567, 218, 2, 'core', 'heelToe', 'Heel-Toe Bass Drum Technique', 'https://www.youtube.com/watch?v=xHqkxHaQ-bI', 'Kick placement at 137 BPM — near ceiling. At this tempo, every mis-hit is audible. Precision over speed: if you can''t land it cleanly, slow down 5 BPM.', 137, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (568, 218, 3, 'apply', NULL, NULL, NULL, 'Drop the syncopated kick into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 44.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (569, 219, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Start the session with single strokes at 141 BPM. Week 44 tempo. Keep the metronome honest — if you can''t hear yourself locking with it, you''re not locked with it.', 141, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (570, 219, 2, 'core', 'bleedMeshuggah', 'Bleed by Meshuggah — Drum Lesson Breakdown', 'https://www.youtube.com/watch?v=QCBr1ws2JYo', 'combined polymeter at 129 BPM. This is near your ceiling. Use the push-breakdown-drop method. If you can''t play it clean 3 times at this tempo, it''s not your tempo yet. Don''t fake it — the groove has to feel mechanical, not effortful.', 129, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (571, 219, 3, 'apply', NULL, NULL, NULL, 'Drop the polymeter kick pattern into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 44.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (572, 220, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 44.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (573, 221, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Foundation check. Single strokes at 142 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 142, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (574, 221, 2, 'core', 'rudingerChannel', 'Alex Rudinger — Full Channel', 'https://www.youtube.com/user/mdterps1042', 'Linear fills at week 45. 9 variations in the toolkit. Today''s goal: chain 3 different variations without stopping. That''s performance-ready linear playing.', 9, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (575, 221, 3, 'apply', NULL, NULL, NULL, 'Drop a linear fill into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 45.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (576, 222, 1, 'warmup', 'singleParadiddle', 'Single Paradiddle', 'https://www.youtube.com/watch?v=-imiZIrGwXE', 'Foundation check. Single strokes at 142 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 142, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (577, 222, 2, 'core', 'dannyCarey', 'Danny Carey''s Tools Of The Trade', 'https://www.youtube.com/watch?v=-Emut0-LYJE', 'Odd time at week 45. 18 grooves in your toolkit. Today''s focus: make it feel like 4/4, not like counting. The groove has to become natural, not calculated.', 18, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (578, 222, 3, 'apply', NULL, NULL, NULL, 'Drop the odd time groove into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 45.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (579, 223, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Foundation check. Single strokes at 142 BPM. Even stick height, even volume, even timing. If anything drifts, slow down 10 BPM and make it right before moving up.', 142, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (580, 223, 2, 'core', 'syncKickWorkout', 'Syncopated Bass Drum Workout (60-90-100bpm)', 'https://www.youtube.com/watch?v=vKq9xk0dUxM', '8-minute groove hold. You should own this by now. If it still feels hard, note that — it''s diagnostic. The goal is effortless, not gritted teeth.', NULL, 480);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (581, 223, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 45.', NULL, NULL);
