INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (623, 239, 3, 'apply', NULL, NULL, NULL, 'Drop a groove you enjoy into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 48.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (624, 240, 1, 'core', NULL, NULL, NULL, 'Consolidation day. No new material. Go back to this week''s hardest drill and play it at a tempo you genuinely own — not the target, the one where it''s clean. Then record 15-30 seconds. You don''t need it to be perfect. You need to hear where you actually are. Week 48.', NULL, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (625, 241, 1, 'warmup', 'singleParadiddleDiddle', 'Single Paradiddle-Diddle', 'https://www.youtube.com/watch?v=0z58p1nd4PQ', 'Warm up with single strokes at 146 BPM. This isn''t the hard part of the session — but don''t sleep through it. Check your grip, check your posture, make it count.', 146, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (626, 241, 2, 'core', 'rudingerChannel', 'Alex Rudinger — Full Channel', 'https://www.youtube.com/user/mdterps1042', 'Linear fills at week 49. 10 variations in the toolkit. Today''s goal: chain 3 different variations without stopping. That''s performance-ready linear playing.', 10, NULL);
INSERT OR IGNORE INTO steps (id, lesson_id, step_order, type, video_id, video_title, video_url, instruction, bpm_target, stamina_target_seconds) VALUES (627, 241, 3, 'apply', NULL, NULL, NULL, 'Drop a linear fill into 8 bars. Don''t think of it as a drill — think of it as something you''d actually play in a song. Loop it until it stops feeling like practice. Week 49.', NULL, NULL);
